    private static string Quickstart() =>
        File.ReadAllText(
            Path.Combine(ProjectRoot().FullName, "examples", "Quickstart", "Program.cs")
        );

    private static string ReadRootFile(string name) =>
        File.ReadAllText(Path.Combine(ProjectRoot().FullName, name));

    /* The info string and the body of every fence tagged csharp, in file order. */
    private static List<(string Info, string Body)> CSharpFences(string text) =>
        System
            .Text.RegularExpressions.Regex.Matches(
                text,
                "^```(csharp[^\n]*)\n(.*?)^```$",
                System.Text.RegularExpressions.RegexOptions.Multiline
                    | System.Text.RegularExpressions.RegexOptions.Singleline
            )
            .Select(match => (match.Groups[1].Value, match.Groups[2].Value))
            .ToList();

    private static string WithoutWhitespace(string text) =>
        string.Concat(text.Where(character => !char.IsWhiteSpace(character)));

