    [Fact]
    public void BhvLangcsharp077TheUsageFenceAndTheQuickstartHoldTheSameStatements()
    {
        /* The quickstart is formatted by CSharpier and the README is not, so the
           statements are compared with the whitespace taken out. */
        var readme = ReadRootFile("README.md");
        var start = readme.IndexOf("\n## Usage\n", StringComparison.Ordinal);
        Assert.True(start >= 0, "README.md has no Usage section");
        var end = readme.IndexOf("\n## ", start + 1, StringComparison.Ordinal);
        var usage = end < 0 ? readme[start..] : readme[start..end];
        var fences = CSharpFences(usage);
        Assert.NotEmpty(fences);
        var quickstart = WithoutWhitespace(Quickstart());

        var position = 0;
        foreach (var line in fences[0].Body.Split('\n'))
        {
            var statement = WithoutWhitespace(line);
            var directive =
                line.StartsWith("using ", StringComparison.Ordinal)
                && !line.StartsWith("using var ", StringComparison.Ordinal);
            if (statement.Length == 0 || directive)
            {
                continue;
            }
            var found = quickstart.IndexOf(statement, position, StringComparison.Ordinal);
            Assert.True(found >= 0, $"expected the quickstart to hold, in order: {line}");
            position = found + statement.Length;
        }
    }

    [Fact]
    public void BhvLangcsharp078EveryCSharpFenceDeclaresItsKind()
    {
        foreach (var name in new[] { "README.md", "SKILLS.md" })
        {
            foreach (var (info, _) in CSharpFences(ReadRootFile(name)))
            {
                Assert.True(info is "csharp file" or "csharp statements", $"{name}: {info}");
            }
        }
    }

    [Fact]
    public void BhvLangcsharp079NoCSharpFenceHoldsAPlaceholderOrAModelBuiltFromNothing()
    {
        foreach (var name in new[] { "README.md", "SKILLS.md" })
        {
            foreach (var (_, body) in CSharpFences(ReadRootFile(name)))
            {
                foreach (var line in body.Split('\n'))
                {
                    var stripped = line.Trim();
                    Assert.False(
                        stripped == "..." || line.Contains("(...)", StringComparison.Ordinal),
                        $"{name}: {line}"
                    );
                    Assert.False(
                        stripped.StartsWith('<') && stripped.EndsWith('>'),
                        $"{name}: {line}"
                    );
                    Assert.False(
                        line.Contains("default!", StringComparison.Ordinal),
                        $"{name}: {line}"
                    );
                    Assert.False(
                        line.Contains("SomeOperation", StringComparison.Ordinal),
                        $"{name}: {line}"
                    );
                }
            }
        }
    }

    [Fact]
    public void BhvLangcsharp080TheMakefileHasAnExamplesTargetThatBuildsTheExamplesDirectory()
    {
        var makefile = ReadRootFile("Makefile");

        Assert.Contains("\nexamples:\n", makefile, StringComparison.Ordinal);
        Assert.Contains("\nexamples-run: examples\n", makefile, StringComparison.Ordinal);
        Assert.Contains(
            "dotnet build examples/Quickstart/Quickstart.csproj",
            makefile,
            StringComparison.Ordinal
        );
    }
}
